//autogenerated:yes
//nolint:revive,govet,errcheck
package standard_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/standard"
	"github.com/stretchr/testify/require"
)

func TestEnum_MAV_PROTOCOL_CAPABILITY(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MAV_PROTOCOL_CAPABILITY
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MAV_PROTOCOL_CAPABILITY_MISSION_FLOAT.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MAV_PROTOCOL_CAPABILITY
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MAV_PROTOCOL_CAPABILITY_MISSION_FLOAT, dec)
	})
}
